        raise ValueError("Invalid duration format")

    hours_str, minutes_str, seconds_str = match.groups()

    total = 0
    components = []

    if hours_str:
        hours = int(hours_str[:-1])
        if hours <= 0:
            raise ValueError("Hours must be positive")
