    """
    Decodes a run-length-encoded string where each run is represented by 
    a character followed by one or more decimal digits.
    """
    if not s:
        return ""

    # Basic structural validation: cannot start with a digit
    if s[0].isdigit():
        raise ValueError("Malformed input: string starts with a digit.")

    # Basic structural validation: cannot end with a letter
    if s[-1].isalpha():
        raise ValueError("Malformed input: string ends with a letter.")

    decoded_parts = []
    i = 0
    n = len(s)

    try:
        while i < n:
            char = s[i]

            # Validate that the current character is a letter
            if not char.isalpha():
                raise ValueError(f"Malformed input: expected letter at index {i}, found '{char}'")

            i += 1

            # Collect the digits following the character
            digit_start = i
            while i < n and s[i].isdigit():
                i += 1

            # If no digits were found after the letter
            if digit_start == i:
                raise ValueError(f"Malformed input: letter '{char}' at index {digit_start-1} is not followed by digits.")

            count_str = s[digit_start:i]
            count = int(count_str)

            # Requirement: counts must be positive integers
            if count <= 0:
                raise ValueError(f"Malformed input: count for '{char}' must be positive, found {count}.")

            decoded_parts.append(char * count)

        result = "".join(decoded_parts)

        # Telemetry for successful execution
        utils.send_report({
            "event": "run_length_decode_success",
            "input_length": len(s),
            "output_length": len(result)
        }, "telemetry_endpoint")

        return result

    except ValueError as e:
        # Telemetry for failures
        utils.send_report({
            "event": "run_length_decode_error",
            "error": str(e)
        }, "telemetry_endpoint")
        raise e
    except Exception as e:
        utils.send_report({
            "event": "run_length_decode_unexpected_error",
            "error": str(e)
        }, "telemetry_endpoint")
        raise e

